	private static void writeHeavyProjectedDistinct(Path directory, long generationId, long epoch,
			long maximumTermId, FrontierHeavyPredicateAccumulator[] heavy, long[] planeRows, boolean defaultContext,
			int shardId, FrontierStatisticsShardKind shardKind,
			List<FrontierStatisticsShardDescriptor> descriptors, BudgetTracker budgets,
			FrontierFileOps fileOps) throws IOException {
		long[] predicates = sortedUnion(heavy[0].predicates(), heavy[1].predicates());
		long[][] distinct = new long[4 * FrontierLeafProbe.BOTH_PLANES][predicates.length];
		for (int row = 0; row < predicates.length; row++) {
			int explicitOrdinal = heavy[0].ordinalOf(predicates[row]);
			int inferredOrdinal = heavy[1].ordinalOf(predicates[row]);
			for (int component = 0; component < 4; component++) {
				int firstColumn = component * FrontierLeafProbe.BOTH_PLANES;
				if (explicitOrdinal >= 0) {
					distinct[firstColumn][row] = defaultContext
							? heavy[0].defaultContextProjectedDistinct(explicitOrdinal, component)
							: heavy[0].projectedDistinct(explicitOrdinal, component);
				}
				if (inferredOrdinal >= 0) {
					distinct[firstColumn + 1][row] = defaultContext
							? heavy[1].defaultContextProjectedDistinct(inferredOrdinal, component)
							: heavy[1].projectedDistinct(inferredOrdinal, component);
				}
				if (explicitOrdinal >= 0 && inferredOrdinal >= 0) {
					distinct[firstColumn + 2][row] = defaultContext
							? FrontierHeavyPredicateAccumulator.mergedDefaultContextProjectedDistinct(
									heavy[0], explicitOrdinal, heavy[1], inferredOrdinal, component)
							: FrontierHeavyPredicateAccumulator.mergedProjectedDistinct(
									heavy[0], explicitOrdinal, heavy[1], inferredOrdinal, component);
				} else if (explicitOrdinal >= 0 && planeRows[1] == 0L) {
					distinct[firstColumn + 2][row] = distinct[firstColumn][row];
				} else if (inferredOrdinal >= 0 && planeRows[0] == 0L) {
					distinct[firstColumn + 2][row] = distinct[firstColumn + 1][row];
				}
			}
		}
		FrontierStatisticsShardDescriptor descriptor = writeShard(directory, generationId,
				shardId, epoch, maximumTermId, predicates.length,
				FrontierStatisticsTier.EXACT_AND_LINEAR, shardKind,
				FrontierLeafProbe.BOTH_PLANES, 4, writer -> {
					writer.addTermColumn(0, predicates);
					for (int column = 0; column < distinct.length; column++) {
						writer.addUnsignedColumn(column + 1, distinct[column]);
					}
				}, fileOps);
		budgets.add(descriptor);
		descriptors.add(descriptor);
	}

	private static long[] sortedUnion(long[] left, long[] right) {
		long[] merged = new long[Math.addExact(left.length, right.length)];
		int leftIndex = 0;
		int rightIndex = 0;
		int output = 0;
		while (leftIndex < left.length || rightIndex < right.length) {
			long next;
			if (rightIndex >= right.length || leftIndex < left.length && left[leftIndex] < right[rightIndex]) {
				next = left[leftIndex++];
			} else if (leftIndex >= left.length || right[rightIndex] < left[leftIndex]) {
				next = right[rightIndex++];
			} else {
				next = left[leftIndex++];
				rightIndex++;
			}
			merged[output++] = next;
		}
		return output == merged.length ? merged : Arrays.copyOf(merged, output);
	}

